 "content": "def transform(grid):
    # Build rays along the 45-degree lines indicated by each 1 marker
    # and each 6 marker; retain all original markers.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for color in (1, 6):
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color:
                    continue
                # Continue the same-color diagonal in both directions.
                for dr, dc in ((1, 1), (1, -1), (-1, 1), (-1, -1)):
                    rr, cc = r + dr, c + dc
                    while 0 <= rr < h and 0 <= cc < w:
                        if out[rr][cc] == 4:
                            out[rr][cc] = color
                        rr += dr
                        cc += dc
    return out
